        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "It's a wonder I haven't abandoned all my ideals, they seem so absurd and impractical. Yet I cling to them because I still believe, in spite of everything, that people are truly good at heart.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "We're all alive, but we don't know why or what for; we're all searching for happiness; we're all leading lives that are different and yet the same.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I hear the approaching thunder that, one day, will destroy us too, I feel the suffering of millions. And yet, when I look up at the sky, I somehow feel that this cruelty too shall end, and that peace and tranquility will return once again.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Go outside, to the country, enjoy the sun and all nature has to offer. Go outside and try to recapture the happiness within yourself; think of all the beauty in yourself and in everything around you and be happy.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I've found that there is always some beauty left - in nature, sunshine, freedom, in yourself; these can all help you. Look at these things, then you find yourself again, and God, and then you regain your balance.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "A person who's happy will make others happy; a person who has courage and faith will never die in misery!", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "For someone like me, it is a very strange habit to write in a diary. Not only that I have never written before, but it strikes me that later neither I, nor anyone else, will care for the musings of a thirteen-year-old schoolgirl.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I've learned one thing: you only really get to know a person after a fight. Only then can you judge their true character!", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "If I read a book that impresses me, I have to take myself firmly by the hand, before I mix with other people; otherwise they would think my mind rather queer.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "You can be lonely even when you're loved by many people, since you're still not anybody's 'one and only'.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I soothe my conscience now with the thought that it is better for hard words to be on paper than that Mummy should carry them in her heart.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Who would ever think that so much went on in the soul of a young girl?", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I trust to luck and do nothing but work, hoping that all will end well.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "People can tell you to keep your mouth shut, but it doesn't stop you having your own opinions. Even if people are still very young, they shouldn't be prevented from saying what they think.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I need to have something besides a husband and children to devote myself to! I don't want to have lived in vain like most people. I want to be useful or bring enjoyment to all people, even those I've never met.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I want to go on living even after my death! And that's why I'm so grateful to God for having given me this gift, which I can use to develop myself and to express all that's inside me!", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "I believe that in the course of the next century the notion that it's a woman's duty to have children will change and make way for the respect and admiration of all women, who bear their burdens without complaint or a lot of pompous words!", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Laziness may look inviting, but only work gives you true satisfaction.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "We're all alive, but we don't know why or what for; we're all searching for happiness; we're all leading lives that are different and yet the same.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Parents can only give good advice or put them on the right paths, but the final forming of a person's character lies in their own hands.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Forgive me, they don't call me a bundle of contradictions for nothing!", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Where there's hope, there's life. It fills us with fresh courage and makes us strong again.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "All people are born equal, all people die in the end and keep nothing of their worldly status. All riches, all power and all greatness exist only for so few years, why then is that mortality clung to so strongly?", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "We all know that a good example is more effective than advice. So set a good example, and it won't take long for others to follow.", Author = "Anne Frank" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Frank", Text = "Who knows, perhaps one day people will listen more to \"the little piece of God\", which we call a conscience, than to their own desires!", Author = "Anne Frank" },
